<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Category;use App\Models\Product;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class ProductController extends Controller { public function index(){return view('admin.products.index',['products'=>Product::with('category')->latest()->paginate(20),'categories'=>Category::where('is_active',true)->orderBy('name')->get()]);} private function data(Request $r,?Product $p=null):array{$d=$r->validate(['title'=>'required|string|max:160','category_id'=>'required|exists:categories,id','price'=>'required|numeric|min:0','unit'=>'required|string|max:50','description'=>'nullable|string','stock_status'=>'required|in:in_stock,out_of_stock','image'=>'nullable|image|max:2048']);unset($d['image']);if($r->hasFile('image')){if($p?->image)Storage::disk('public')->delete($p->image);$d['image']=$r->file('image')->store('products','public');}return $d;} public function store(Request $r){Product::create($this->data($r));return back()->with('status','Product created.');} public function update(Request $r,Product $product){$product->update($this->data($r,$product));return back()->with('status','Product updated.');} public function destroy(Product $product){if($product->image)Storage::disk('public')->delete($product->image);$product->delete();return back()->with('status','Product deleted.');}}
